// Okuma metinleri için şerh katmanı: metin girişi (müellif, şerhler, okuma yolu) ve satır satır şerh notları.
// satir anahtarı, metindeki satırın "no" değeridir. okuma: [taraf (âlim id veya ad), açıklama].
window.METIN_SERH = window.METIN_SERH || {};
Object.assign(window.METIN_SERH, {
  tahavi: {
    bag: ["alim:tahavi", "alim:ebuhanife", "kavram:iman", "kavram:tenzih", "kavram:kesb", "kavram:tevhid", "mesele:sifatlar", "mesele:imanartar", "metin:akaid-nesefi"],
    giris: {
      muellif: "tahavi",
      paragraf: [
        "Ebû Ca'fer et-Tahâvî (ö. 321/933) Mısırlı bir muhaddis ve fakihtir. Şâfiî fıkhını dayısı Müzenî'den okumuş, sonra Hanefî mezhebine geçmiştir. Şerhu Meâni'l-âsâr ve Şerhu Müşkili'l-âsâr gibi eserleriyle, hadis ile fıkhı birbirine bağlama çabasının önde gelen temsilcisidir.",
        "Akîde, Eş'arî (ö. 324) ve Mâtürîdî (ö. 333) ile aynı nesilde, onlardan bağımsız olarak yazılmıştır. Kelâm tartışmalarına girmeden, Kûfe fakihlerinin inancını kısa hükümler hâlinde sıralar. Bu sadelik sayesinde Hanefî-Mâtürîdî, Eş'arî ve Selefî çevrelerin her biri metni kendi okumasıyla şerh etmiştir. Bu yüzden metin, ekoller arasındaki ortak zemini ve ayrılık noktalarını aynı sayfada görmek için elverişli bir aynadır.",
      ],
      serhler: [
        ["baberti", "Şerhu Akîdeti't-Tahâvî", "Hanefî-Mâtürîdî çizgide, kelâm terimleriyle yazılmış bir şerh."],
        ["Sirâceddin el-Gaznevî (ö. 773/1372)", "Şerhu'l-Akîdeti't-Tahâviyye", "Hanefî-Mâtürîdî; kısa ve öğretici."],
        ["İbn Ebi'l-İz el-Hanefî (ö. 792/1390)", "Şerhu'l-Akîdeti't-Tahâviyye", "Hanefî bir kadı olmakla birlikte İbn Teymiyye ve İbnü'l-Kayyim'in görüşlerine dayanır; bugün Selefî çevrelerde en çok okunan şerhtir."],
        ["Abdülganî el-Meydânî (ö. 1298/1881)", "Şerhu'l-Akîdeti't-Tahâviyye", "Dımaşklı Hanefî âlim; Mâtürîdî okumanın son dönem örneği."],
        ["Saîd Fûde", "eş-Şerhu'l-kebîr ale'l-Akîdeti't-Tahâviyye", "Çağdaş ve kapsamlı bir Eş'arî şerh."],
      ],
      okuma: [
        "Metni okurken iki şeye dikkat edilmelidir. Birincisi: Tahâvî kelimeleri kelâm terimi olarak değil, nasların diliyle kullanır; “cihet”, “kelâm” ve “üstünde olmak” gibi ifadeler şârihlerce sonraki dönemin terimleriyle açılmıştır. İkincisi: Metnin birçok cümlesi belli bir fırkaya cevaptır (Cehmiyye, Mu'tezile, Hâricîler, Mürcie, Râfıza). Cümlenin kime karşı söylendiğini bilmek, ne söylediğini anlamanın yarısıdır.",
      ],
    },
    satir: {
      1: { not: "Tahâvî inancı kendi adına değil, Ebû Hanîfe ve iki talebesine nispetle sunar. Böylece akidenin şahsi bir yorum değil, bir ilim silsilesinin aktarımı olduğunu gösterir. “Milletin fakihleri” ifadesi de dikkat çekicidir: Erken dönemde fıkıh akideyi ve ahlâkı da kapsıyordu. Ebû Hanîfe'ye nispet edilen el-Fıkhu'l-ekber adı bu geniş anlamın izidir.",
        soru: ["Bir inancı “kendi görüşüm” diye değil, “şu silsilenin inancı” diye sunmak neyi değiştirir?", "İnancın keyfî olmadığını ve sorumluluğunun bir ilim zincirine bağlandığını gösterir. Okuyan da o zincirin kaynaklarına başvurup sözü sınayabilir."] },
      2: { not: "Bölüm Allah'ı önce birlik, sonra benzersizlik, sonra kudret ile niteler. “Başlangıcı olmadan kadîm, sonu olmadan daim” ifadesi, Hadîd 3'teki “el-Evvel, el-Âhir” isimlerinin kelâmî karşılığıdır. “İhtiyaç duymadan yaratır” cümlesi, yaratmanın Allah'a bir eksiklik gidermek için değil, cömertliğinin eseri olarak gerçekleştiğini söyler.",
        okuma: [["Mâtürîdî şârihler", "“Kadîm” kelimesini Allah için kullanmakta sakınca görmez; ezelî olanı ifade eden yerleşik bir terimdir."], ["İbn Ebi'l-İz", "“Kadîm”in Allah'ın güzel isimlerinden olmadığını, nasslarda geçen “el-Evvel” isminin tercih edilmesi gerektiğini söyler; ama kastedilen manayı doğru bulur."]],
        soru: ["“Bir külfete girmeden rızık verir” cümlesi, rızık kaygısına nasıl bir cevap verir?", "Tükenme korkusu, alanın kendi sınırlılığından doğar. Veren için zahmet olmayan bir şeyi, kul kendi darlığıyla ölçmemelidir."] },
      3: { not: "Bu bölüm, sıfatların yaratılmışlarla birlikte ortaya çıktığı fikrine karşıdır: Allah yaratmadan önce de “Hâlık”tır. Hanefî-Mâtürîdî kelâmın ayırt edici tezi olan tekvîn sıfatının izleri buradadır: Yaratma (tekvîn) ezelî bir sıfattır, yaratılan (mükevven) ise sonradandır.",
        okuma: [["maturidi", "Tekvîn ezelî ve müstakil bir sıfattır. Allah'ın yaratıcı oluşu, yaratılanın var olmasına bağlı değildir."], ["esari", "Eş'arîler tekvîni ayrı bir sıfat saymaz; yaratmayı kudretin yaratılana taalluku olarak görür. Bu yüzden ezeldeki “Hâlık” ismini “yaratmaya kadir” anlamında anlar."], ["İbn Ebi'l-İz", "Allah'ın ezelden beri dilediğinde fiil işleyen olduğunu, fiillerinin cinsinin kadîm, tek tek fiillerin ise dilemesine bağlı olduğunu savunur. Bu, İbn Teymiyye'nin görüşüdür."]],
        soru: ["Ezelde yaratılmış hiçbir şey yokken Allah'a “Hâlık” demek ne anlama gelir?", "İsim, bir fiilin sonucundan değil, sıfatın kendisinden alınmıştır. Şârihlerin ayrıldığı yer bu sıfatın ne olduğudur; ortak oldukları nokta, Allah'ın yaratılmışlarla bir kemal kazanmadığıdır."] },
      4: { not: "Tahâvî kaderi iki kelimeyle dengeler: lütuf (fadl) ve adalet (adl). Hidayet bir lütuftur, kimse onu hak ederek almaz; saptırma ise haksızlık değil adalettir, çünkü kul kendi seçimiyle o yola girmiştir. Bu ifade hem kulun hiç iradesi olmadığını söyleyen Cebriyye'ye hem de Allah'ın kulun fiilini dilemediğini söyleyen Kaderiyye'ye karşıdır.",
        okuma: [["Mu'tezile'ye cevap", "Mu'tezile, Allah'ın kötülüğü dilemesini adaletine aykırı görmüştü. Ehl-i sünnet “dilemek” ile “razı olmak”ı birbirinden ayırır: Allah küfrün olmasını diler ama ondan razı değildir (Zümer 7)."]],
        soru: ["Kendi hayatındaki hidayeti bir “lütuf” olarak görmek, başkasının sapmasına bakışını nasıl değiştirir?", "Hidayet hak edilmiş bir ödül değilse, onu taşıyan kişi büyüklenemez; sapana da üstten değil, merhametle ve dua ile bakar."] },
      5: { not: "“Peygamberlerin sonuncusu” ifadesinden sonra gelen “Ondan sonraki her peygamberlik iddiası sapıklıktır” cümlesi, metnin yazıldığı dönemde de bu tür iddiaların görüldüğünü hatırlatır. “Cinlere ve insanlara gönderilmiş” kaydı, risaletin evrenselliğini açıkça ifade eder (Sebe' 28).",
        soru: ["Hâtemiyyet inancı, bir mümin için “yeni bir vahiy” beklentisini nasıl yönlendirir?", "Rehberliği yeni bir vahiyde değil, tamamlanmış vahyi anlamada aramaya yöneltir. İlmî çaba ve ictihad bu tamamlanmışlığın içinde yürür."] },
      6: { not: "Bu bölüm Mihne'nin yankısıdır. Me'mûn'un Kur'an'ın mahluk olduğunu resmî inanç yaptırması ve Ahmed b. Hanbel'in buna direnişi, Tahâvî'nin çocukluğunda henüz taze bir hatıraydı. “Keyfiyeti olmaksızın söz olarak O'ndan zuhur etmiştir” ifadesi hem kelâmın Allah'tan olduğunu hem de keyfiyetinin bilinmediğini söyler.",
        okuma: [["Mâtürîdî ve Eş'arî şârihler", "Allah'ın ezelî kelâmı harf ve sesten münezzeh bir sıfattır (kelâm-ı nefsî). Okunan, yazılan ve ezberlenen lafızlar bu kelâma delâlet eder. “Kur'an mahluk değildir” sözü bu ezelî kelâm içindir."], ["İbn Ebi'l-İz", "Allah'ın harf ve sesle, dilediğinde konuştuğunu, Kur'an'ın lafzıyla ve manasıyla Allah'ın kelâmı olduğunu savunur; kelâm-ı nefsî anlayışını eleştirir."], ["ahmed", "Mihne sırasında Kur'an'ın mahluk olmadığını söylemekten vazgeçmemiş, “mahluk değildir” deyip ötesine geçmemeyi tercih etmiştir."]],
        soru: ["Elindeki mushafın sayfaları yaratılmışsa, “Kur'an mahluk değildir” derken neyi kastediyoruz?", "Ekollerin hepsi kâğıdın, mürekkebin ve sesin yaratılmış olduğunu kabul eder. Tartışma, bunların delâlet ettiği kelâmın Allah'ın sıfatı oluşunu nasıl ifade edeceğimiz üzerinedir."] },
      7: { not: "Tek cümlelik bu bölüm tenzihin temel kuralıdır: Allah'a nispet edilen hiçbir sıfat, insandaki karşılığının manasıyla anlaşılamaz. Cümle sıfatları reddetmeyi değil, onları insan sıfatlarına benzetmeyi hedef alır; hemen sonraki bölümde rü'yet ispat edilir.",
        soru: ["Allah'ın “gazap ettiğini” okuduğumuzda zihnimizde beliren insanî öfke resmi neden bu cümlenin yasakladığı şeydir?", "İnsandaki öfke bir değişim, bir zaaf ve bir tepkidir; Allah'ın gazabı bunlardan münezzehtir. Kelime ortaktır, mana ayrıdır."] },
      8: { not: "Rü'yet, Ehl-i sünnet ile Mu'tezile arasındaki en keskin ayrılıklardandır. Mu'tezile, görmenin bir yön ve karşı karşıya gelmeyi gerektirdiğini düşünerek reddetmiş, Kıyâme 23'teki “nâzıra” kelimesini “bekleyen” diye yorumlamıştı. Tahâvî “kuşatma ve keyfiyet olmaksızın” kaydıyla, bu görmenin dünyadaki görme gibi olmadığını söyler.",
        okuma: [["Mâtürîdî ve Eş'arî şârihler", "Rü'yet yön, mesafe ve karşı karşıya gelme olmaksızın gerçekleşir; bu şartlar dünyadaki görmeye aittir."], ["İbn Ebi'l-İz", "Müminlerin Rablerini yukarıdan göreceklerini, yön nefyinin nasslarla uyuşmadığını söyler."]],
        soru: ["Tahâvî rü'yeti ispat ederken neden hemen “te'vil etmeyiz, vehmetmeyiz” der?", "Hem inkâr eden yorumu hem de görmeyi zihindeki bir resme dönüştüren hayali aynı anda dışlamak için. İsbat ile tenzih birlikte yürür."] },
      9: { not: "Metnin en çok alıntılanan cümlelerinden biri: “İslâm'ın ayağı ancak teslimiyet zemininde sabit durur.” Bu, aklı devre dışı bırakmak değil, aklın sınırını bilmektir. İnsan idrakini aşan bir meselede ısrar etmek, kişiyi “ne tam mümin ne açık inkârcı” bir bocalamaya sürükler.",
        okuma: [["gazali", "İlcâmü'l-avâm'da sıradan insanın müteşâbih sıfatlar karşısındaki görevlerini takdis, tasdik, acizi itiraf, susmak, kurcalamamak ve bilgisini ehline bırakmak gibi maddelerle sayar. Tahâvî'nin teslim vurgusuna benzer bir terbiye önerir."]],
        soru: ["Bir sorunun cevabını bilmemek ile o soruyu yanlış sormak arasındaki fark nedir?", "Bilinmeyen bir şey araştırılabilir; yanlış sorulan bir soru ise cevabı ne olursa olsun zihni karıştırır. Teslimiyet bazen soruyu doğru kurmayı öğrenmektir."] },
      10: { not: "Şârihler arasında en çok tartışılan cümle buradadır: “Altı yön onu kuşatmaz.” Tahâvî bu bölümde iki uçtan aynı anda sakındırır: sıfatları reddetmekten (ta'tîl) ve Allah'ı benzetmekten (teşbîh).",
        okuma: [["Mâtürîdî ve Eş'arî şârihler", "Cümleyi Allah'ın mekân ve yönden münezzeh oluşunun açık delili sayar. “Sınır, uç, organ, araç” nefyi de cisimlik ihtimalini kapatır."], ["İbn Ebi'l-İz", "Cümledeki kelimeleri birden fazla anlama gelen (mücmel) lafızlar olarak niteler. Yaratılmış yönlerin Allah'ı kuşatmadığı doğrudur; ama bu cümleden Allah'ın yücelik (uluvv) sıfatının nefyi çıkarılmamalıdır."]],
        soru: ["Aynı cümleden iki ayrı sonuç çıkarılabiliyorsa, muğlak olan metnin kendisi midir, yoksa okurun beraberinde getirdiği sorular mı?", "Tahâvî'nin döneminde “cihet” tartışması henüz bu kadar terimleşmemişti; şârihler sonraki tartışmaları metne taşıdı. Metni kendi bağlamında okumak, ona sonraki soruları yüklemeden önce gelir."] },
      11: { not: "İsrâ (Mescid-i Harâm'dan Mescid-i Aksâ'ya gece yolculuğu) Kur'an'la, mi'rac (göğe yükseliş) ise sahih hadislerle sabittir. Bu yüzden şârihler İsrâ'yı inkârın küfür, mi'racı inkârın ise sapkınlık olduğunu söyler. “Uyanıkken ve bedeniyle” kaydı, mi'racın bir rüya olduğu görüşüne karşıdır; bu görüş Hz. Âişe ve Muâviye'ye nispet edilmiş, ancak rivayetlerin senedi zayıf bulunmuştur.",
        okuma: [["Misak", "Â'râf 172'deki misak iki türlü anlaşılmıştır: Âdem'in sulbünden çıkarılan zürriyetin fiilen söz vermesi (rivayetlere dayanan görüş) ve Allah'ın insan fıtratına tevhid delillerini yerleştirmesi (temsilî yorum). Tahâvî'nin “misak haktır” demesi ikisini de dışlamaz."]],
        soru: ["Peygamber'in en yüce makama yükseldiği gecenin sonunda ümmetine getirdiği hediye namazdır. Bu ilişki namaza bakışı nasıl değiştirir?", "Namaz, mi'racın ümmete açılan kapısı olarak görülmüştür: Kul her gün beş defa Rabbinin huzuruna yükselir."] },
      12: { not: "“Ameller sonuçlarına göredir” Buhârî'de (6607) geçen bir hadisin lafzıdır. Bu cümle hem ümitsizliği hem güveni frenler: İyi giden, sonundan emin olamaz; kötü giden de dönüş kapısının kapanmadığını bilir. Ezelî bilgi kulu zorlamaz; Allah, kulun özgürce yapacağını bilir.",
        soru: ["“Allah zaten biliyor” düşüncesi neden çabayı anlamsızlaştırmaz?", "Bilmek, sebep olmak değildir. Allah'ın bilgisi kulun seçimini ortadan kaldırmaz; kul, bilinmeyen sonucuna değil, önündeki göreve bakar."] },
      13: { not: "Tahâvî kaderin varlığını değil, sırrını araştırmayı yasaklar. Kadere iman farzdır; her olayın neden öyle takdir edildiğini sorgulamak ise insan idrakinin dışındadır. “Niçin yaptı?” sorusunun reddi, Allah'ın hikmetini inkâr değil, bu hikmetin her zaman bize açılmayacağını kabuldür.",
        okuma: [["Hikmet tartışması", "Eş'arîler, Allah'ın fiillerinin bir amaca bağlanamayacağını vurgular. Mâtürîdîler ve İbn Teymiyye çizgisi ise fiillerin hikmetli olduğunu, ancak bu hikmetin her zaman bilinemeyeceğini söyler. Tahâvî'nin cümlesi iki okumaya da açıktır."]],
        soru: ["Başına gelen bir musibette “Neden?” sorusu ile “Şimdi ne yapmalıyım?” sorusu arasında nasıl bir fark var?", "Birincisi çoğu zaman cevapsız kalır ve kişiyi kendi içine kapatır; ikincisi kulluğun sorusudur ve kişiyi harekete geçirir."] },
      14: { not: "“Mevcut ilim”, vahyin bildirdiği ve insanın öğrenmekle yükümlü olduğu bilgidir; “bulunmayan ilim” ise gayb ve kaderin sırrıdır. Birincisini inkâr etmek dini reddetmek, ikincisini iddia etmek de Allah'a ait bir alanı sahiplenmektir. Bu ayrım bugün kehanet, falcılık ve “gizli bilgi” iddialarına karşı da bir ölçüdür.",
        soru: ["“Bilinmesi gerekeni bilmemek” ile “bilinemeyeni bildiğini sanmak”tan hangisi bugün daha yaygın?", "Her ikisi de bilgi ahlâkının bozulmasıdır; Tahâvî ikisini de küfürle ilişkilendirerek ilmin sınırlarını ciddiye almayı ister."] },
      15: { not: "Bölümün son cümleleri, İbn Abbas'a yapılan meşhur nasihati (Kırk Hadis 19) hatırlatır. Kaderin yazılmış olması kulun tedbirini boşa çıkarmaz; onu sonuç kaygısından kurtarır. Hz. Ömer, veba bölgesine girmeme kararını sorgulayana “Allah'ın kaderinden yine Allah'ın kaderine kaçıyoruz” demiştir (Buhârî, 5729).",
        soru: ["Kader yazılmışsa tedbire ne gerek var?", "Tedbir de kaderin içindedir. Hz. Ömer'in sözü, sebeplere sarılmanın kadere itiraz değil, kaderin bir parçası olduğunu gösterir."] },
      16: { not: "Arş ve kürsî Kur'an'da geçer (Bakara 255, Tâhâ 5). Tahâvî hemen ardından “Allah arşa muhtaç değildir” der; böylece istivâ âyetlerinin Allah'ı bir mekâna ihtiyaç duyan bir varlık gibi düşündürmesinin önünü keser.",
        okuma: [["Mâtürîdî ve Eş'arî şârihler", "“Her şeyin üstünde” ifadesini kudret, galibiyet ve mertebe üstünlüğü olarak anlar."], ["İbn Ebi'l-İz", "İfadeyi zâtın yüceliği (uluvv) olarak anlar ve “muhtaç olmamak” ile “üstünde olmak” arasında bir çelişki görmez."]],
        soru: ["“Muhtaç değildir” vurgusu, istivâ âyetlerini okurken zihne hangi soruyu sordurmalıdır?", "“Bu ifade Allah'ı bir şeye bağımlı mı gösteriyor?” Cevap hayırsa, mana hangi ekolün yorumuyla açılırsa açılsın tenzihe uygun kalır."] },
      17: { not: "“Allah hakkında derin tartışmalara dalmayız, din hakkında münakaşa etmeyiz” cümlesi kelâmı bütünüyle reddetmek değildir; ilmi olmadan ve hakkı arama niyeti taşımadan yapılan tartışmayı yasaklar. Kıble ehlini Müslüman saymanın ölçüsü, Peygamber'in getirdiklerini kabul etmektir; ameldeki kusur bu adlandırmayı kaldırmaz.",
        soru: ["Bir tartışmanın hakkı aramak için mi, yoksa kazanmak için mi yapıldığını nasıl anlarız?", "Hakkı arayan, karşısındakinin haklı olduğu yeri görmekten sevinir; kazanmak isteyen ise o yeri görmezden gelir."] },
      18: { not: "Bu bölüm iki uca karşıdır: Büyük günah işleyeni kâfir sayan Hâricîler ile “iman varken günah zarar vermez” diyen aşırı Mürcie. “Helal saymadıkça” kaydı önemlidir: Günahı işlemek fısktır; onu helal saymak ise bir dinî hükmü inkâr olduğu için küfürdür.",
        okuma: [["Emn ve ye's", "Hanefî akaid ve fıkıh kitaplarında Allah'ın azabından emin olmak ile rahmetinden ümit kesmek küfür sayılır. Şârihler bunu bir duygu dalgalanması olarak değil, Allah'ın vaadini veya tehdidini yok sayan yerleşik bir inanç olarak açıklar."]],
        soru: ["Hem korkuyu hem ümidi taşımak neden “iki kanat” diye anlatılır?", "Tek kanatla uçulmaz: Yalnız ümit gevşekliğe, yalnız korku ümitsizliğe götürür. Tahâvî'nin hak yolu bu ikisinin arasındadır."] },
      19: { not: "Hanefî iman tanımı: dil ile ikrar, kalp ile tasdik. Amel imanın parçası sayılmaz; “iman birdir ve ehli onun aslında eşittir” cümlesi bunun sonucudur. Üstünlük imanın aslında değil, takva ve amelde ortaya çıkar.",
        okuma: [["ebuhanife", "İmanı ikrar ve tasdik olarak tanımlar; amel imanın kemaline aittir."], ["Eş'arî ve Mâtürîdî âlimlerin çoğu", "İmanın rüknünü yalnızca kalbin tasdikinde görür; dilin ikrarını, kişiye dünyada Müslüman hükümlerinin uygulanması için aranan bir şart olarak değerlendirir."], ["Ehl-i hadis ve İbn Ebi'l-İz", "İmanı söz, inanç ve amelin bütünü olarak görür ve onun artıp eksildiğini savunur. İbn Ebi'l-İz, Hanefî bir şârih olarak bu noktada Tahâvî'den ayrılır; yine de Ebû Hanîfe'nin tutumunun Mürcie'ninkiyle aynı olmadığını, ameli terk edeni kâfir saymamakta iki tarafın buluştuğunu kabul eder."]],
        soru: ["İmanın aslında eşit olmak ile takvada farklılaşmak arasındaki ayrım, başkalarına bakışımızı nasıl etkiler?", "Bir Müslümanın imanını küçümseme hakkını kimseye vermez; ama herkesi takvada yarışa çağırır."] },
      20: { not: "Ehl-i sünnetin ümit cümlesi: Tevhid üzere ölen büyük günah sahibi ebedî olarak cehennemde kalmaz. Bu, Mu'tezile'nin “iki konum arasında bir konum” görüşüne ve büyük günah sahibi için ebedî azap tezine cevaptır. Bölümün bir dua ile bitmesi, akidenin bir tartışma metni olduğu kadar bir yakarış olduğunu da gösterir.",
        soru: ["Metnin ortasında “Allah'ım, bizi İslâm üzere sabit kıl” duasının yer alması ne anlatır?", "İnanç bilgisinin sahibine bir güvence vermediğini; sebatın da bir lütuf olduğunu ve istenmesi gerektiğini."] },
      21: { not: "Fâsık imamın arkasında namaz kılmak, Hanefî fıkhında mekruh olmakla birlikte sahihtir. Kimseyi belirli olarak cennetlik veya cehennemlik ilan etmemek, ancak nassın bildirdiği kişiler için istisna kabul eder. “Kılıcı hak etmiş olanlar” ifadesi kısas, had ve devlete karşı silahlı isyan gibi fıkhî hâllere işaret eder.",
        soru: ["İçini bilmediğin birini dışındakine göre değerlendirmek ile onun kalbi hakkında hüküm vermek arasındaki sınır nerededir?", "Dünya hükümleri zahire göredir; kalbin hükmü Allah'a aittir. Peygamber'in Üsâme'ye “Kalbini yarıp da mı baktın?” diye sitem ettiği olay bu sınırı çizer (Müslim, 96)."] },
      22: { not: "Bu bölüm ilk asırların fitnelerinden çıkarılmış bir dersi yansıtır: Silahlı isyanlar çoğu zaman giderilmek istenen zulümden daha büyük kan ve kargaşa doğurmuştur. Ancak metin itaati kayıtlar: Günah emredilmedikçe. Bu sınır, iyiliği emretme ve hakkı söyleme görevini kaldırmaz.",
        okuma: [["İlk dönemdeki farklı tavırlar", "Hz. Hüseyin'in Kerbelâ'ya yürüyüşü ve İbnü'l-Eş'as isyanına katılan kurrâ gibi örnekler, ilk nesillerde bu meselenin tartışmalı olduğunu gösterir. Ebû Hanîfe'nin Zeyd b. Ali hareketine maddi destek verdiği de rivayet edilir. Tahâvî'nin cümlesi, bu tecrübelerden sonra yerleşen Sünnî kanaati özetler."], ["Çağdaş tartışma", "Bugün bazı âlimler bu hükmün silahlı isyanla ilgili olduğunu, barışçıl muhalefet, hesap sorma ve hukukî denetimi kapsamadığını vurgular; bazıları ise itaatin kapsamını daha geniş tutar."]],
        soru: ["“Zulmetseler bile isyan etmeyiz” ile “günah emrederlerse itaat etmeyiz” cümleleri birlikte nasıl bir ahlâk çizer?", "Kargaşayı önlemeyi önceleyen ama vicdanı teslim etmeyen bir ahlâk: Silaha başvurmamak, zulme ortak olmayı kabul etmek anlamına gelmez."] },
      23: { not: "Bir fıkıh meselesinin akide metnine girmesi şaşırtıcı görünebilir. Sebebi, mestler üzerine meshi reddeden gruplara karşı bunun bir sünnet alameti hâline gelmesidir. Ebû Hanîfe'ye nispet edilen bir sözde Ehl-i sünnetin alametleri arasında “iki şeyhi (Ebû Bekir ve Ömer) üstün tutmak, iki damadı (Osman ve Ali) sevmek ve mestler üzerine meshetmek” sayılır. Hac ve cihadın iyi ve kötü yöneticilerle sürmesi de ibadetin yöneticinin şahsî durumuna bağlanmadığını gösterir.",
        soru: ["Bir topluluğun kimliğini belirleyen işaretler bazen neden küçük fıkhî ayrıntılar olur?", "Ayrılıklar çoğu zaman büyük ilkelerde değil, onları görünür kılan uygulamalarda belirginleşir. Bu işaretlerin değeri, temsil ettikleri ilkeden gelir."] },
      24: { not: "Kabir azabı ve sorgusu Kur'an'da işaretle (Mü'min 46), hadislerde açıkça bildirilir. Bazı Mu'tezile ve Hâricîlerin kabir azabını reddetmesi, bu maddenin akide metinlerine girmesine sebep olmuştur. “Kabir ya cennet bahçelerinden bir bahçe ya da cehennem çukurlarından bir çukurdur” cümlesi, Tirmizî'nin rivayet ettiği bir hadisin lafzıdır (2460).",
        soru: ["Kabir sorusunun üç sorudan (Rabbin, dinin, peygamberin) oluşması, hayatı nasıl özetler?", "Kime kulluk ettiğin, hangi yolu yürüdüğün ve kimi örnek aldığın. Sorular ezberle değil, yaşanmış bir hayatla cevaplanır."] },
      25: { not: "Cennet ve cehennemin şu an yaratılmış olduğu, Mu'tezile'nin bir kısmının “henüz yaratılmamıştır” görüşüne; ebedî oluşları ise Cehm b. Safvân'ın “ikisi de yok olacaktır” görüşüne karşıdır. Bölümün sonunda hayır ve şerrin takdir edildiği tekrar edilir.",
        okuma: [["subki", "İbn Teymiyye ve İbnü'l-Kayyim'e nispet edilen “cehennem azabı bir gün sona erer” görüşüne karşı el-İ'tibâr bi-bekāi'l-cenneti ve'n-nâr adlı bir reddiye yazmıştır. İbn Ebi'l-İz de şerhinde bu tartışmaya yer verir. Cumhurun kanaati, Tahâvî'nin ifadesiyle ikisinin de yok olmayacağı yönündedir."]],
        soru: ["“Herkes yaratıldığı şeye varır” cümlesi bir kaderciliğe mi, yoksa bir yöneliş sorumluluğuna mı işaret eder?", "Hadiste bu söz soranlara “Amel edin, herkese yaratıldığı şey kolaylaştırılır” diye cevap verilmiştir. Sonuç sırdır; görev ise açıktır."] },
      26: { not: "Bölüm kelâmın en ince meselelerinden birini, güç (istitâat) meselesini iki kısma ayırır: Fiille birlikte olan ve Allah'ın tevfiki olan güç ile fiilden önce bulunan sağlık ve imkân. Yükümlülük ikincisine bağlanır; bu yüzden gücün yetmediği bir şeyle yükümlü tutulmak reddedilir. “Kesb” kavramı da fiilin hem Allah'ın yaratması hem kulun kazanması oluşunu birlikte ifade eder.",
        okuma: [["esari", "Kulun kudreti fiille birliktedir ve fiilde etkili değildir; kul fiili kesb eder. Gücün yetmeyeceği şeyle yükümlülüğün aklen mümkün olduğunu söyleyen Eş'arîler de vardır; ancak bunun fiilen vuku bulmadığında herkes birleşir."], ["maturidi", "Kula bir seçme gücü (cüz'î irade) verilmiştir; kul bu iradesiyle fiile yönelir, Allah da fiili yaratır. Gücün yetmeyeceği şeyle yükümlü tutmak hikmete aykırıdır."]],
        soru: ["“Lâ havle ve lâ kuvvete illâ billâh” sözü günlük hayatta hangi anlarda söylenir ve Tahâvî'nin açıklaması ona ne katar?", "Çoğunlukla çaresizlik anında söylenir. Tahâvî onu her iyiliğin ve her kötülükten dönüşün tevfike bağlı olduğunu itiraf eden bir kulluk cümlesine dönüştürür."] },
      27: { not: "Ölülere dua ve sadakanın ulaşması, Necm 39'u (“İnsan için çalıştığından başkası yoktur”) mutlak anlayan görüşe karşıdır. Kur'an okumanın sevabının ölüye ulaşması ise mezhepler arasında tartışmalıdır: Hanefî ve Hanbelîler ulaşacağını kabul eder; Şâfiîlerin meşhur görüşü ulaşmayacağı yönündedir, ancak sonraki Şâfiîlerin çoğu okuyup sevabının bağışlanması için dua edildiğinde ulaşacağını söyler.",
        okuma: [["Sıfatları te'vil eden kelâmcılar", "“Gazap eder, razı olur” ifadesini cezalandırma ve sevap verme iradesi olarak açıklar."], ["Selef ve İbn Ebi'l-İz", "Gazap ve rızayı keyfiyetsiz olarak Allah'ın sıfatları kabul eder ve te'vil etmez. Tahâvî'nin “yaratılmışlardan hiçbiri gibi değil” kaydı her iki okumanın da ortak zeminidir."]],
        soru: ["“Göz açıp kapayıncaya kadar bile Allah'tan müstağni olunamaz” cümlesi, kendine yeterlilik duygusunu nasıl sınar?", "Kendine yetme duygusu çoğu zaman işler yolunda giderken doğar. Tahâvî bu duygunun bir an bile hakikat olmadığını, onu küfre kadar götürebilecek bir yanılgı olduğunu hatırlatır."] },
      28: { not: "Sahabeye bakışta Tahâvî iki aşırılığa karşıdır: Bir kısmını severken haddi aşanlar ve bir kısmından teberrî edenler. Hilafet sırası, Ehl-i sünnetin büyük çoğunluğunca fazilet sırası olarak da kabul edilir. Metnin devamında, burada alınmayan kısımda, cennetle müjdelenen on sahabe, Peygamber'in eşleri ve soyu da hayırla anılır.",
        okuma: [["Osman–Ali tafdîli", "İlk dönemde bazı Kûfe âlimleri Hz. Ali'yi Hz. Osman'dan üstün tutmuş, ancak hilafet sırasının meşruiyetini tartışmamıştır. Sonradan Ehl-i sünnet hilafet sırasını fazilet sırası olarak benimsemiştir."]],
        soru: ["Sahabe arasındaki ihtilaflar okunurken “ancak hayırla anarız” ilkesi neyi korur?", "Tarihi bilmeyi yasaklamaz; bu tarihi bir kin ve taraf tutma malzemesine dönüştürmeyi yasaklar. Onlar hakkındaki hüküm Allah'a aittir."] },
      29: { not: "Selef âlimlerini “ancak güzellikle anmak”, onları eleştirmeyi değil, hakaret ve tahkiri yasaklar; ilmî tenkit geleneğin içindedir. “Tek bir peygamber bütün velîlerden üstündür” cümlesi, bazı aşırı tasavvufî iddialara karşı bir sınırdır.",
        okuma: [["ibnarabi", "Füsûsü'l-hikem'deki “velâyet nübüvvetten üstündür” diye anlaşılan ifadeleri, şârihlerince aynı peygamberin velâyet yönünün nübüvvet yönünden üstünlüğü olarak açıklanır; bir velînin bir peygamberden üstün olduğu anlamına gelmez."], ["Keramet", "Mu'tezile'nin bir kısmı, mucizeyle karışacağı gerekçesiyle kerameti reddetmişti. Ehl-i sünnet kerameti kabul eder; mucizeden farkı, peygamberlik iddiası ve meydan okuma bulunmamasıdır."]],
        soru: ["Bir âlimi eleştirmek ile onu küçümsemek arasındaki çizgi nerededir?", "Eleştiri sözün delilini tartar; küçümseme ise kişiyi hedef alır. İlk nesiller birbirine en sert itirazları ederken bile edebi korumuştur."] },
      30: { not: "Kâhin ve falcıyı tasdik etmeme maddesi, “Kim bir kâhine gidip söylediğini tasdik ederse Muhammed'e indirileni inkâr etmiş olur” hadisine dayanır (Tirmizî, 135). “Cemaat hak, ayrılık azaptır” cümlesi de Peygamber'in “Allah'ın eli cemaatin üzerindedir” sözünü hatırlatır (Tirmizî, 2166).",
        soru: ["Burç yorumları ve fal uygulamalarının “eğlence” diye sunulması bu maddeyi geçersiz kılar mı?", "Tasdik etmeden merakla bakmak ile ona göre karar vermek arasında fark vardır; ancak alışkanlık, kalpte gizli bir tasdik doğurabilir. Tahâvî'nin ölçüsü gaybı Allah'a ait bilmektir."] },
      31: { not: "Metnin özeti dört çift zıt kavramla verilir: aşırılık ve ihmal, teşbih ve ta'tîl, cebir ve kader inkârı, emn ve ye's. Her biri Ehl-i sünnetin “vasat” (Bakara 143) duruşunu tarif eder. Bu denge, iki ucun tam ortası değil, her ikisinin de haklı yanını kuşatan bir duruştur.",
        soru: ["Kendi dindarlığında bu dört çiftten hangisinde bir uca daha yakınsın?", "Metni bir ayna olarak okumak, onu yalnızca başkalarının yanlışlarını tespit için değil, kendi dengesini görmek için kullanmaktır."] },
    },
  },

  hikem: {
    bag: ["alim:ibnataullah", "alim:sazili", "kavram:ihlas", "kavram:zuhd", "kavram:halmakam", "konu:dua", "konu:zikir"],
    giris: {
      muellif: "ibnataullah",
      paragraf: [
        "İbn Atâullah el-İskenderî (ö. 709/1309) Şâzeliyye yolunun üçüncü halkasıdır: Şeyhi Ebü'l-Abbâs el-Mürsî, onun şeyhi de Ebü'l-Hasan eş-Şâzelî'dir. Mâlikî bir fakih olarak Ezher'de ders vermiş, Kahire'de vefat etmiştir. İbn Teymiyye ile tartışmalarıyla da bilinir.",
        "el-Hikem, kısa ve veciz cümlelerle tasavvuf yolunun özünü verir: amelden çok Allah'ın lütfuna güvenmek, tedbiri Allah'a bırakmak, nefsin gizli hilelerini tanımak. Eser tekkelerde olduğu kadar medreselerde de okunmuş, yüzyıllar boyunca şerh edilmiştir.",
      ],
      serhler: [
        ["İbn Abbâd er-Rundî (ö. 792/1390)", "Gaysü'l-mevâhibi'l-aliyye", "En yaygın klasik şerh."],
        ["Ahmed Zerrûk (ö. 899/1493)", "", "Hikem'i defalarca şerh ettiği nakledilir; fıkıh ile tasavvufu dengeleyen bir okuma."],
        ["İbn Acîbe (ö. 1224/1809)", "Îkāzü'l-himem", "Şâzelî geleneğinden, ayrıntılı ve tasavvuf terminolojisine dayalı."],
        ["buti", "el-Hikemü'l-Atâiyye: Şerh ve tahlîl", "Hikmetleri çağdaş insanın sorularıyla buluşturan bir şerh."],
      ],
      okuma: [
        "Hikmetler bir defada okunup geçilecek cümleler değildir. Her biri bir hâli tarif eder; okur kendi hâlinde o cümlenin karşılığını aramadıkça anlam açılmaz. Şârihlerin ortak uyarısı şudur: Hikem amel ve tedbiri terk etmeye değil, onlara bağlanan kalbi Allah'a çevirmeye çağırır.",
      ],
    },
    satir: {
      1: { not: "Hikmet amel etmeyi değil, amele dayanmayı eleştirir. Amele güvenen hata ettiğinde ümidini yitirir, çünkü ümidini ameline bağlamıştır. Allah'ın lütfuna güvenen ise iyilikte kibirlenmez, hatada da ümitsizliğe düşmez. Bu, “Hiç kimseyi ameli cennete sokmaz” hadisinin tasavvuf dilindeki karşılığıdır.",
        soru: ["Bir ibadeti kaçırdığında hissettiğin sıkıntı, Allah'a karşı mahcubiyet mi, yoksa kendi “temiz sicilinin” bozulmasına üzüntü mü?", "İkincisi, ümidin amele bağlandığının işaretidir; birincisi ise tevbeye ve yeniden yönelmeye götürür."] },
      2: { not: "“Sevâbıku'l-himem” güçlü ve öne atılan azimler demektir. Bazı sâliklerin manevi yönelişinden olağanüstü sonuçlar beklenir; İbn Atâullah bunun bile kaderin dışına çıkamayacağını söyler. Cümle çabayı küçümsemez; çabanın sonucunu Allah'a bırakmayı öğretir.",
        soru: ["Bir hedefe bütün gücünle yönelip sonucunu bırakmak mümkün mü?", "Çiftçi tohumu eker, toprağı sular, yağmuru ise bekler. Azim tohumu ekmektir; sonucu bırakmak yağmuru beklemektir."] },
      3: { not: "Tedbir, sonuçları kendi gücüyle kurmaya ve kontrol etmeye çalışmaktır. İbn Atâullah bu konuyu et-Tenvîr fî iskāti't-tedbîr adlı ayrı bir kitapta işlemiştir. Şârihler, terk edilmesi istenenin sebeplere sarılmak değil, kalbin sonuç kaygısıyla meşgul olması olduğunu vurgular: Elin sebepte, kalbin Allah'ta olması.",
        okuma: [["Övülen ve yerilen tedbir", "Şârihler iki tedbiri ayırır: Dinin emrettiği, işi yapmadan önce düşünmek ve hazırlanmak övülmüştür; yerilen ise Allah'ın takdirine itiraz taşıyan ve kalbi sürekli meşgul eden tedbirdir."]],
        soru: ["Gelecek kaygısı seni plan yapmaya mı, yoksa uykusuzluğa mı götürüyor?", "Plan yapmak sebebe sarılmaktır; uykusuzluk ise sonucu kendi omzuna almaktır. Hikmet ikincisini bırakmaya çağırır."] },
      4: { not: "Rızık garanti edilmiştir (Hûd 6, Zâriyât 22-23); kulluk ise kuldan istenmiştir. İnsanın enerjisini garanti edilene harcayıp istenende gevşek davranması, basiretin, yani kalp gözünün körelmesidir. Hikmet çalışmayı yasaklamaz; önceliklerin sırasını düzeltir.",
        soru: ["Gününün en dinç saatleri hangisine gidiyor: garanti edilene mi, senden istenene mi?", "Zamanın dağılımı kalbin önceliklerini ele verir. Hikmet bu dağılıma bakmaya davet eder."] },
      5: { not: "Duanın kabulü, istenenin aynen ve hemen verilmesi değildir. Peygamber duanın üç şekilde karşılık bulduğunu bildirmiştir: İstenen verilir, âhirete saklanır veya bir kötülük onunla savılır (Ahmed b. Hanbel, Müsned). İbn Atâullah buna “Senin için seçtiğinde ve dilediği vakitte” kaydını ekler.",
        soru: ["Kabul edilmediğini düşündüğün bir duaya bugün geriye dönüp baktığında ne görüyorsun?", "Çoğu zaman istenenin verilmemesinin de bir cevap olduğu sonradan anlaşılır. Duayı sürdürmek, bu cevaba güvenmektir."] },
      6: { not: "Herkes için tek bir ibadet kalıbı yoktur: Kimine namaz, kimine oruç, kimine hizmet, kimine ilim kapısı daha çok açılır. Allah ibadetleri çeşitlendirmiştir ki her hâlin bir kapısı olsun ve kul usandığında bir ibadetten diğerine geçebilsin.",
        soru: ["Senin için en kolay açılan ibadet kapısı hangisi ve diğerlerini nasıl ihmal etmeden ona yönelebilirsin?", "Farzlar herkes için ortaktır; nafilelerde ise kişinin hâline uygun kapı aramak meşrudur."] },
      7: { not: "Bu hikmet “Ameller niyetlere göredir” hadisinin tasavvuf dilindeki karşılığıdır. İhlâssız amel, ruhu çekilmiş bir beden gibidir: Şekli ayaktadır ama hayatı yoktur. Şârihler ihlâsın derecelerini de anlatır: cennet umarak veya cehennemden korkarak yapılan amel ve yalnızca Allah'ın rızası için yapılan amel.",
        soru: ["Bir ameli kimse görmeyecek olsa yine aynı şekilde yapar mıydın?", "Bu soru, amelin ruhunun yerini gösterir. Görülme ihtimaliyle değişen amelde ruh başka yerdedir."] },
      8: { not: "“Humûl”, tanınmamak ve gözden uzak olmaktır. Tohum toprağa gömülmeden filizlenirse kökü zayıf kalır; manevi hayat da şöhretle başlarsa sağlam olmaz. Bu hikmet özellikle ilim ve irşad yoluna yeni girenler için bir uyarıdır.",
        soru: ["Görünürlüğün çok değerli sayıldığı bir çağda “gömülmeden filizlenmek” neye benzer?", "Henüz olgunlaşmadan görünür olmak, dinî hayatı bir sunuma dönüştürür; kök yerine vitrin büyür."] },
      9: { not: "Uzlet insanlardan kaçmak değil, tefekkür için bir alan açmaktır. Hikmetteki kayıt önemlidir: Faydalı olan, kalbi tefekkür meydanına sokan yalnızlıktır; zihni boş bırakan veya vesveseye açan yalnızlık değil.",
        soru: ["Gününde hiçbir uyarının (ses, ekran, konuşma) olmadığı birkaç dakika var mı?", "Tefekkür, zihne yer açılmadıkça başlamaz. Uzlet bugün çoğu zaman sadece bir süreliğine susturulan bir telefondur."] },
      10: { not: "Dört soru dört engeli sıralar: kalbe yerleşmiş eşya suretleri, şehvet zincirleri, gaflet cünüplüğü ve tevbe edilmemiş hatalar. “Cünüplük” benzetmesi dikkat çekicidir: Cünüp namaza giremediği gibi, gafletle kirlenen kalp de huzura giremez; buradaki guslün karşılığı tevbedir.",
        soru: ["Kalbinin aynasına en çok hangi suretler işlenmiş durumda?", "Gün boyu en çok düşündüğün şeyler o aynadaki suretlerdir. Ayna silinmeden ışığı yansıtmaz."] },
      11: { not: "İnsan çoğu zaman “Şartlar değişse daha iyi bir kul olurdum” diye düşünür. İbn Atâullah bu düşünceyi bir nefis hilesi sayar: Allah seni bulunduğun yerde kullanmak isteseydi, bir şeyi değiştirmeye gerek kalmadan kullanırdı. Bu, değişimi yasaklamak değil, kulluğu ertelemeyi engellemektir.",
        soru: ["“Şu iş bitsin, sonra...” diye ertelediğin bir kulluk var mı?", "Hikmet bu ertelemeyi sorgular: Kulluğun yeri, şu an içinde bulunduğun hâldir."] },
      12: { not: "Arkadaş seçiminin iki ölçüsü vardır: hâl ve söz. Hâli seni harekete geçirmeyen kişinin sözü ne kadar güzel olursa olsun etkisi azdır; sözü seni Allah'a götürmeyenin hâli ne kadar parlak olursa olsun yol göstermez. Metinde hemen ardından gelen hikmet, kendinden daha kötü hâldekilerle arkadaşlığın kişiye kendini iyi gösterebileceği uyarısını yapar.",
        soru: ["Yanında olduğunda seni Allah'a yaklaştıran biri var mı?", "Böyle bir arkadaş en değerli servettir. Hikmet onu aramaya ve korumaya çağırır."] },
      13: { not: "Amelin değeri hacminde değil, çıktığı kalbin hâlindedir. Dünyaya bağlanmamış bir kalpten çıkan az amel bereketlidir; dünyaya düşkün bir kalpten çıkan çok amel ise riya ve beklentiyle ağırlığını kaybeder.",
        soru: ["Az ama gönülden yapılan ile çok ama hesapla yapılan amel arasında hangisine daha yakınsın?", "Hikmet sayıya değil kaynağa bakmayı öğretir; aynı amel iki farklı kalpten iki farklı ağırlıkla çıkar."] },
      14: { not: "Zikri huzur gelmiyor diye bırakmak, nefsin “mükemmel değilse hiç olmasın” hilesidir. İbn Atâullah'ın devamında söylediği gibi, gafletle yapılan zikir uyanıklıkla yapılan zikre, o da huzurla yapılan zikre, o da Allah'tan başkasının kaybolduğu zikre götürebilir. Dilin zikri kalbin zikrinin kapısıdır.",
        soru: ["“Kalbim yanında değil” diye bıraktığın bir zikir veya dua var mı?", "Dilin devam etmesi, kalbin döneceği yolu açık tutar. Hikmet bırakmayı değil, sürdürmeyi önerir."] },
      15: { not: "İnsanlardan gelen yalnızlık, kırgınlık veya dışlanma kapanmış bir kapı gibi görünür. Hikmet bunu bir davet olarak okur: Allah kulunu insanlara dayanmaktan kurtarıp kendisiyle ünsiyete çağırmaktadır. Bu, insanlardan kopmayı değil, kalbin dayanağını değiştirmeyi öğretir.",
        soru: ["Son yaşadığın bir yalnızlık seni nereye yöneltti: kırgınlığa mı, Allah'a mı?", "Aynı yalnızlık iki kapıya da açılabilir. Hikmet ikincisini seçmenin mümkün olduğunu hatırlatır."] },
      16: { not: "Zillet, başkasına muhtaç olmanın ve ona boyun eğmenin hâlidir; tamah ise başkasının elindekine göz dikmektir. Bu hikmet, “İnsanların elindekine gönül bağlama ki seni sevsinler” tavsiyesini içeren hadisle birlikte okunur (İbn Mâce, 4102; Kırk Hadis 31).",
        soru: ["Kimin karşısında kendini küçük hissediyorsun ve bunun altında bir beklenti yatıyor mu?", "Çoğu zaman zilletin kökünde bir tamah vardır. Beklentiyi kesmek, başı kaldırmanın ilk adımıdır."] },
      17: { not: "Önceki hikmetin devamı: Hürriyet, sahip olmadığın şeylere ümit bağlamamaktır. Göz diktiğin şey seni yönetir; ümidini kestiğin şeyin üzerinde hiçbir gücü kalmaz. Bu hikmet kölelikten kurtuluşu dış zincirlerde değil, kalbin bağlarında arar.",
        soru: ["Seni en çok yöneten arzun hangisi?", "Onu tanımak, ondan özgürleşmenin başlangıcıdır. Hikmet, hürriyetin bir kayıp değil kazanç olduğunu söyler."] },
      18: { not: "Verilen bir nimet bazen kulu Allah'tan uzaklaştırır; bu yüzden aslında bir mahrumiyettir. Esirgenen bazen kulu Allah'a yöneltir; bu yüzden aslında bir ihsandır. Hemen ardından İbn Atâullah şöyle der: “Mahrum bırakmasıyla sana anlayış kapısını açarsa, mahrum bırakmak vermenin ta kendisi olur.”",
        soru: ["Hayatında bir mahrumiyetin sonradan bir kazanca dönüştüğü bir an hatırlıyor musun?", "O an, hikmetin kendi hayatındaki tefsiridir. Benzer bir mahrumiyeti bugün de aynı gözle okumak mümkündür."] },
      19: { not: "Hikmetlerin en çok yanlış anlaşılabilecek olanlarından biri: Günah övülmez. Övülen, günahın ardından gelen kırıklık ve Allah'a muhtaçlık duygusudur; yerilen ise itaatin ardından gelen kibirdir. Ölçü amelin dış görünüşü değil, kalpte bıraktığı izdir.",
        okuma: [["Yanlış okumaya karşı", "Şârihler bu hikmetin günaha cesaret vermek için okunamayacağını, kıyaslamanın günah ile itaat arasında değil, kırık kalp ile kibirli kalp arasında yapıldığını vurgular."]],
        soru: ["Bir ibadetten sonra kendini başkalarından üstün hissettiğin oluyor mu?", "Bu his, itaatin ardında bıraktığı izdir. Hikmet bu izi silmek için ibadeti bırakmayı değil, onu Allah'ın bir lütfu olarak görmeyi önerir."] },
      20: { not: "Allah'ın adaleti ile muamele edilen kişinin en küçük günahı bile büyüktür, çünkü kimse Allah'ın hakkını tam veremez. Lütfu ile muamele edilenin en büyük günahı bile bağışlanabilir. Bu hikmet hem küçük günahı hafife almayı hem de büyük günah karşısında ümitsizliği engeller; Tahâvî'nin “emn ile ye's arasındaki yol”una benzer.",
        soru: ["Hangi günahı “küçük” diye hafife alıyorsun?", "Günahın küçüklüğü, karşısındakinin büyüklüğüyle ölçüldüğünde kaybolur. Ümidi ise yalnızca lütfun genişliği besler."] },
      21: { not: "Başlangıç nurlu olursa son da nurlu olur. “Başlangıç” burada yola giriş niyetidir: Allah için başlayan yolculuk, dönemeçlerinde sarsılsa da yönünü bulur. Şârihler bunu “Ameller sonuçlarına göredir” hadisiyle birlikte okur; ikisi birbirini tamamlar.",
        soru: ["Şu an başladığın bir işin niyetini bir cümleyle yazabilir misin?", "Niyeti açıkça ifade etmek, yolun sonunda nereye varmak istediğini netleştirir."] },
      22: { not: "Övgü, övenin bildiğine dayanır; kınama ise kişinin kendi hakkında bildiğine. İnsanların övgüsüne güvenmek, onların bilmediği şeyleri yok saymaktır. Hz. Ebû Bekir'in övüldüğünde “Allah'ım, beni onların sandığından daha hayırlı kıl, bilmediklerini bağışla” dediği rivayet edilir.",
        soru: ["Övüldüğünde içinde ilk beliren duygu nedir?", "Sevinç doğaldır; tehlike, övgünün kişinin kendini tanımasının yerine geçmesidir."] },
      23: { not: "Allah katındaki değerin ölçüsü, seni hangi işte tuttuğudur. Taat, ilim, hizmet veya zikirle meşgul edilmen bir ikramdır; boş işlerle meşgul olman ise bir uyarıdır. Bu ölçü kişiyi başkalarını değil kendini değerlendirmeye çağırır.",
        soru: ["Bu hafta seni en çok meşgul eden üç şey neydi?", "O liste, hikmetin sorduğu sorunun cevabıdır. Ondan ümit veya uyarı çıkarmak okurun kendi işidir."] },
      24: { not: "Şehvetin kalpten çıkması için iki yol vardır: sarsan bir korku veya huzursuz eden bir özlem. Birincisi celâl, ikincisi cemâl yoludur. Hikmet, yalnızca yasak ve tehditle şehvetin söküp atılamayacağını, daha güçlü bir sevginin onun yerini alması gerektiğini de öğretir.",
        soru: ["Bir alışkanlığı bırakmak için sana daha çok ne güç veriyor: korku mu, özlem mi?", "İkisi de meşrudur; ama kalıcı olan, yerine daha güzel bir şey konulan boşluktur."] },
    },
  },

  semail: {
    bag: ["alim:tirmizi", "kavram:sunnet", "konu:rahmet", "hadis:aile-ehil", "hadis:iman-sevgi"],
    giris: {
      muellif: "tirmizi",
      paragraf: [
        "Tirmizî (ö. 279/892), Sünen'iyle Kütüb-i Sitte'nin müelliflerinden biridir. eş-Şemâil'de Resûlullah'ın ﷺ dış görünüşünü, giyimini, yemesini, konuşmasını, gülmesini, ibadetini, ahlâkını ve vefatını elli altı bab ve dört yüze yakın rivayetle toplar. Eser Peygamber'i bir hukuk kaynağı olmanın ötesinde, sevilecek ve örnek alınacak bir insan olarak tanıtır.",
        "Şemâil'in rivayetleri sıhhat bakımından eşit değildir: Bir kısmı Buhârî ve Müslim'de de geçer, bir kısmı zayıftır. Âlimler helal ve haram bildirmeyen fazilet ve şemâil rivayetlerinde, uydurma olmamak şartıyla daha geniş davranmıştır.",
      ],
      serhler: [
        ["aliyyulkari", "Cem'u'l-vesâil fî şerhi'ş-Şemâil", "Geniş ve rivayet tahliline dayalı bir şerh."],
        ["Abdürraûf el-Münâvî (ö. 1031/1622)", "", "Çoğunlukla Aliyyü'l-Kārî'nin şerhiyle birlikte basılan şerh."],
        ["bacuri", "el-Mevâhibü'l-ledünniyye ale'ş-Şemâili'l-Muhammediyye", "Medreselerde en çok okunan haşiye."],
      ],
      okuma: [
        "Şemâil Peygamber'i bir kurallar listesine indirgemeden tanımanın yoludur. Her rivayette iki soru sorulabilir: Bu davranış onun hangi ahlâkını gösteriyor ve bu ahlâk benim hayatımda nerede karşılık bulur?",
      ],
    },
    satir: {
      1: { kelime: [["الطَّوِيلُ الْبَائِنُ", "aşırı uzun, boyuyla göze batan"], ["الأَمْهَقُ", "kireç gibi, kansız görünen beyaz"], ["الآدَمُ", "esmer, koyu buğday tenli"], ["الْجَعْدُ الْقَطَطُ", "sık kıvırcık saç"], ["السَّبْطُ", "dümdüz, yatık saç"]],
        not: "Enes'in tarifi her özelliği iki uç arasında verir: ne çok uzun ne kısa, ne bembeyaz ne esmer, ne kıvırcık ne düz. Şârihler bu üslubun Peygamber'in yaratılışındaki itidali gösterdiğini söyler. Aynı tasvir Buhârî (3548) ve Müslim'de (2347) de geçer.",
        soru: ["Bir insanı “iki uç arasında” anlatmak, onun ahlâkı hakkında ne düşündürür?", "Dış yaratılıştaki denge, ahlâktaki itidalin bir aynası gibidir: ne aşırı sertlik ne gevşeklik."] },
      2: { kelime: [["ذُو لِمَّةٍ", "saçı kulak memesini geçen"], ["حُلَّةٌ", "aynı kumaştan iki parçalı elbise"]],
        not: "Saç uzunluğu için üç kelime kullanılır: vefre (kulak memesine kadar), limme (onu geçen) ve cümme (omuza ulaşan). Rivayetler Peygamber'in saçının farklı zamanlarda bu ölçüler arasında olduğunu gösterir. Rivayet Müslim'de (2337) de vardır.",
        okuma: [["ibnulkayyim", "Zâdü'l-meâd'da “kırmızı hulle”nin düz kırmızı değil, kırmızı ve siyah çizgili bir Yemen kumaşı olduğunu söyler. Erkeğin düz kırmızı giymesini mekruh görenler bu yoruma dayanır."], ["Diğer âlimler", "Rivayetin zahirine dayanarak kırmızı giymeyi caiz görmüştür."]],
        soru: ["Peygamber'in güzel giyinmesi, dindarlık ile özenli görünüş arasındaki ilişkiye ne söyler?", "Güzel giyinmek kibir değildir; kibir hakkı reddetmek ve insanları küçük görmektir. Özen, insanlara ve Allah'ın nimetine saygıdır."] },
      3: { kelime: [["لَيْلَةٌ إِضْحِيَانٌ", "bulutsuz, ay ışığıyla aydınlanmış gece"]],
        not: "Câbir b. Semüre gözünü bir aya bir Peygamber'e çevirerek bir karşılaştırma yapar ve hükmünü verir. Şârihler onun aydan güzel oluşunu, ayın ışığının ödünç, onun nurunun ise hidayet nuru olmasıyla da açıklar. Tirmizî bu rivayeti Sünen'inde de nakleder (2811).",
        soru: ["Bir sahabînin gözünden yapılan bu kıyas, Peygamber sevgisinin nasıl bir şey olduğunu anlatır?", "Seven, sevdiğini en güzel bildiği şeyle kıyaslar ve onu daha güzel bulur. Bu sevgi, gözün ötesinde kalbin bir tanıklığıdır."] },
      4: { kelime: [["بَدِيهَةً", "ansızın, ilk görüşte"], ["هَابَهُ", "heybetinden çekindi"], ["نَاعِتُهُ", "onu vasfeden, anlatan"]],
        not: "Heybet ile sevginin birlikte anılması Peygamber'in ahlâkındaki dengeyi gösterir: Uzaktan bakan saygı duyar, yakından tanıyan sever. Hz. Ali'nin uzun tasviri, Peygamber'in dış görünüşüne ve tavırlarına dair en kapsamlı anlatımlardan biridir.",
        soru: ["Seni yakından tanıyanlar mı daha çok seviyor, uzaktan tanıyanlar mı?", "Yakın ilişkide görülen ahlâk gerçek ahlâktır. Uzaktan saygı görmek kolay, yakından sevilmek zordur."] },
      5: { kelime: [["يَسْرُدُ", "sözü art arda, hızla sıralar"], ["فَصْلٌ", "açık, birbirinden ayrılan söz"]],
        not: "Buhârî'deki rivayete göre Hz. Âişe bu sözü, odasının yanında oturup hadisleri art arda sıralayan bir sahabî için söylemiştir (3568); şârihler onun Ebû Hüreyre olduğunu belirtir. Enes de Peygamber'in bir sözü anlaşılsın diye üç defa tekrar ettiğini anlatır (Buhârî, 95).",
        soru: ["Bir şeyi öğretirken hızı mı, anlaşılmayı mı önemsiyorsun?", "Peygamber'in konuşması, dinleyenin ezberleyebileceği kadar tane taneydi. Öğretmek, söyleyenin değil dinleyenin hızına göre yapılır."] },
      6: { not: "Peygamber'in gülmesi çoğunlukla tebessümdü; azı dişleri görününceye kadar güldüğü anlar da rivayet edilmiştir (Buhârî, 6087). Şârihler, “Çok gülmeyin; çok gülmek kalbi öldürür” hadisini de hatırlatır (Tirmizî, 2305; İbn Mâce, 4193). Ölçü gülmeyi yasaklamak değil, kalbi gafletle dolduran aşırılığı engellemektir.",
        soru: ["Tebessüm bir sadaka ise, gün içinde kimlere bu sadakayı vermeyi ihmal ediyorsun?", "Çoğu zaman en yakınlar: aile, iş arkadaşları, her gün karşılaşılan insanlar."] },
      7: { kelime: [["تُدَاعِبُنَا", "bizimle şakalaşıyorsun"]],
        not: "Şemâil'in bu babında Peygamber'in şakalarına örnekler vardır: Enes'e “Ey iki kulaklı!” demesi (Şemâil, 234), binek isteyen birine “Seni devenin yavrusuna bindireceğim” deyip adam şaşırınca “Her deve bir devenin yavrusu değil mi?” buyurması (Şemâil, 237; Ebû Dâvûd, 4998) ve yaşlı bir kadına “Cennete yaşlı kadın girmez” deyip ardından herkesin oraya genç olarak gireceğini açıklaması (Şemâil, 239). Hepsinde şaka doğruluğu bozmaz.",
        okuma: [["Şakanın ölçüsü", "Âlimler şakanın ölçüsünü üç kayıtla belirler: yalan içermemek, kimseyi incitmemek ve ciddiyeti giderecek kadar alışkanlık hâline gelmemek."]],
        soru: ["Senin şakaların bu üç ölçüden hangisini en çok zorluyor?", "Çoğu zaman ikincisi: Gülme bir başkasının incinmesi pahasına olursa şaka olmaktan çıkar."] },
      8: { kelime: [["انْتَفَخَتْ", "şişti"], ["شَكُورًا", "çok şükreden"]],
        not: "Rivayet Buhârî (1130) ve Müslim'de (2819) de geçer. İbadeti bir borç ödeme veya bağışlanma kazanma çabası olarak değil, bir şükür ifadesi olarak görmenin en güzel örneğidir. Âlimler buradan, mağfiret müjdesinin amel terkine değil, amelin artmasına yol açması gerektiği sonucunu çıkarır.",
        soru: ["İbadetlerini daha çok bir borç olarak mı, bir şükür olarak mı yaşıyorsun?", "Borç bittiğinde rahatlanır; şükür ise nimet devam ettikçe sürer. Peygamber'in cevabı ikinciyi gösterir."] },
      9: { kelime: [["أَزِيزٌ", "kaynama sesi, uğultu"], ["الْمِرْجَلُ", "kazan"]],
        not: "Rivayet Ebû Dâvûd (904) ve Nesâî'de (1214) de vardır. Fakihler buradan, namazda Allah korkusuyla ağlamanın namazı bozmadığı sonucunu çıkarır. Hanefîler ise dünyevi bir acı veya musibet sebebiyle sesli ağlamanın namazı bozacağını söyler.",
        soru: ["Namazda en son ne zaman bir âyetin anlamı seni durdurdu?", "Ağlamak bir hedef değildir; ama okunanın anlaşılması kalbin cevap vermesine kapı açar."] },
      10: { kelime: [["تَهْمِلَانِ", "yaş döküyorlardı"]],
        not: "Buhârî (4582) ve Müslim'in (800) rivayetinde Peygamber âyete gelindiğinde “Yeter şimdi” buyurur. Nisâ 41, her ümmete kendi peygamberinin, bu ümmete de Peygamber'in şahit getirileceğini bildirir; şahitliğin ağırlığı onun gözyaşının sebebi olarak yorumlanmıştır. Kur'an'ı başkasından dinlemek de bir sünnettir.",
        soru: ["Kur'an'ı en son ne zaman okumadan, sadece dinleyerek takip ettin?", "Dinlemek, okurken kaçan bir dikkati açar. Peygamber bu yüzden başkasından dinlemeyi sevdiğini söylemiştir."] },
      11: { kelime: [["لَا تُطْرُونِي", "beni aşırı övmeyin, övgüde haddi aşmayın"]],
        not: "Hadis Buhârî'de (3445) de vardır. Yasaklanan, Hristiyanların Hz. Îsâ'yı ilahlaştırması gibi Peygamber'i kulluk sınırının dışına taşıyan övgüdür. Bûsîrî Kasîdetü'l-Bürde'de bu hadise işaretle “Hristiyanların peygamberleri hakkında iddia ettiklerini bırak; sonra onu dilediğin gibi öv” der.",
        okuma: [["Medih ve sınırı", "Âlimlerin çoğu, Hassân b. Sâbit'ten Bûsîrî'ye uzanan na't geleneğini bu sınır içinde meşru görmüştür. Bazı âlimler ise bu tür övgülerde ölçünün kolayca aşılabileceği uyarısını öne çıkarır."]],
        soru: ["Peygamber'i en güzel nasıl övebiliriz?", "Kendi tarifiyle: “Allah'ın kulu ve elçisi.” Kulluk, onun en yüksek makamıdır; elçilik ise ona uyulmasını ister."] },
      12: { kelime: [["يَفْلِي", "(elbisesini) ayıklar, gözden geçirir"]],
        not: "Hz. Âişe'nin cevabı, “Evde ne yapardı?” sorusuna verilmiştir. Buhârî'deki benzer rivayette “Ailesinin hizmetinde olurdu; namaz vakti gelince namaza çıkardı” denir (676). Peygamberlik onu ev işlerinden muaf tutmamıştır.",
        soru: ["Evdeki işlerin “kimin işi” olduğuna dair alışkanlıklarımızı bu rivayet nasıl sorgular?", "Ümmetin en meşgul insanı kendi işini kendi görüyordu. Ev hizmeti bir küçüklük değil, onun sünnetidir."] },
      13: { kelime: [["أُفٍّ", "bıkkınlık ifadesi (İsrâ 23'te de geçer)"]],
        not: "Enes, annesi Ümmü Süleym tarafından küçük yaşta Peygamber'in hizmetine verilmişti. Bir çocuğun on yıl boyunca hiç azarlanmaması, terbiyede sabrın ve hoşgörünün örneğidir. Hadis Buhârî (6038) ve Müslim'de (2309) de vardır.",
        soru: ["Yanında çalışan veya senden küçük olan birine en son ne zaman “Bunu niye yaptın?” dedin?", "Hesap sormak bazen gereklidir; ama Peygamber'in tavrı, hatanın çoğu zaman azarla değil sabırla düzeldiğini gösterir."] },
      14: { kelime: [["فَاحِشًا", "yaratılıştan kaba sözlü"], ["مُتَفَحِّشًا", "kabalığı kendine huy edinen"], ["صَخَّابًا", "bağırıp çağıran"]],
        not: "Buhârî'de (2125) Abdullah b. Amr, Peygamber'in Tevrat'taki vasfını naklederken aynı ifadeleri kullanır: “Kaba ve katı değildir, çarşılarda bağırıp çağırmaz, kötülüğe kötülükle karşılık vermez; affeder ve bağışlar.” Tirmizî bu rivayeti Sünen'inde de nakleder (2016).",
        soru: ["Kötülüğe kötülükle karşılık vermemek bir zayıflık mıdır?", "Kendini tutabilmek güç ister. Affetmek, karşılık verebilecek olanın erdemidir."] },
      15: { not: "Hadis Buhârî (6034) ve Müslim'de (2311) de geçer. Şârihler “Hayır demedi” sözünü, isteneni olduğunda verdiği, olmadığında ise reddetmek yerine güzel bir söz söylediği veya sustuğu şeklinde açıklar. Nitekim İsrâ 28, verecek bir şey yokken “yumuşak bir söz” söylemeyi emreder.",
        soru: ["Birinin isteğini karşılayamadığında onu nasıl geri çeviriyorsun?", "Vermek her zaman mümkün olmayabilir; ama kırmadan geri çevirmek her zaman mümkündür."] },
      16: { kelime: [["الْعَذْرَاءُ", "evlenmemiş genç kız"], ["الْخِدْرُ", "genç kızın perdesi, odası"]],
        not: "Hadis Buhârî (3562) ve Müslim'de (2320) de vardır. Hayâsı hakkı söylemesine engel olmamıştır: Hz. Âişe'nin ifadesiyle o, kendi nefsi için asla intikam almamış, ancak Allah'ın haram kıldığı bir şey çiğnendiğinde Allah için öfkelenmiştir (Buhârî, 3560; Müslim, 2327).",
        soru: ["Hayâ ile çekingenlik arasındaki fark nedir?", "Hayâ kötülükten çekinmektir; hakkı söylemekten çekinmek ise hayâ değil zaaftır. Peygamber'de ikisi birbirini tamamlıyordu."] },
      17: { kelime: [["نَسْتَوْقِدُ", "(yemek pişirmek için) ateş yakarız"]],
        not: "Buhârî'deki rivayette (2567) Hz. Âişe, Urve'ye iki ay boyunca evlerinde ateş yanmadığını, geçimlerinin “iki siyah şey”den, hurma ve sudan ibaret olduğunu anlatır; Müslim'de de benzeri vardır (2972). Şârihler bunun çoğu zaman bir zorunluluk değil bir tercih olduğunu, Peygamber'in eline geçeni dağıttığını vurgular.",
        soru: ["İhtiyaç ile istek arasındaki çizgiyi sen nereye çekiyorsun?", "Peygamber'in evi, dünyanın imkânlarına sahip olup onlara bağlanmamanın örneğidir. Zühd yokluk değil, kalbin bağımsızlığıdır."] },
    },
  },
});
